	let d12 = dx12 * dx12 + dy12 * dy12 + dz12 * dz12;
	let d13 = dx13 * dx13 + dy13 * dy13 + dz13 * dz13;
	let d21 = dx21 * dx21 + dy21 * dy21 + dz21 * dz21;
	let d22 = dx22 * dx22 + dy22 * dy22 + dz22 * dz22;
	let d23 = dx23 * dx23 + dy23 * dy23 + dz23 * dz23;
